from pathlib import Path
import hashlib,json,sys,os,math
for name in ('OMP_NUM_THREADS','MKL_NUM_THREADS','OPENBLAS_NUM_THREADS','NUMEXPR_NUM_THREADS'):os.environ[name]='4'
os.environ['CUDA_VISIBLE_DEVICES']=''
import numpy as np
from threadpoolctl import threadpool_limits
TASK=Path("C:/projects/double-descent-dl-vs-gbdt/artifacts/research/R14/20261108T073937-26f816e66d/tasks/response-study")
P=json.loads((TASK.parents[1]/'inputs/research/stages/R14/inputs/protocol.json').read_text(encoding='utf-8'))
def readj(path):return json.loads(path.read_text(encoding='utf-8'))
def readrows(path):return [json.loads(s) for s in path.read_text(encoding='utf-8').splitlines() if s.strip()]
def digest(path):
 h=hashlib.sha256()
 with path.open('rb') as f:
  for b in iter(lambda:f.read(1048576),b''):h.update(b)
 return h.hexdigest()
def arrayhash(a):
 a=np.ascontiguousarray(a)
 return hashlib.sha256(json.dumps({'dtype':a.dtype.str,'shape':list(a.shape)},sort_keys=True).encode()+b'\0'+a.tobytes()).hexdigest()
errors={}
def compare(label, actual, expected, tol=1e-10, rtol=1e-10):
 a=np.asarray(actual);b=np.asarray(expected)
 assert a.shape==b.shape,(label,a.shape,b.shape)
 assert np.isfinite(a).all() and np.isfinite(b).all(),label
 e=float(np.max(np.abs(a-b))) if a.size else 0.
 errors[label]=max(errors.get(label,0.),e)
 assert np.allclose(a,b,atol=tol,rtol=rtol),(label,e,tol,rtol)
def target(teacher,x):
 return x.sum(1)/2 if teacher=='linear' else (x[:,0]*x[:,1]+x[:,2]*x[:,3])/np.sqrt(2)
A=readj(TASK/'analysis.json');C=readrows(TASK/'contexts.jsonl');D=readrows(TASK/'directions.jsonl');F=readrows(TASK/'forecast_rows.jsonl');S=readrows(TASK/'feature_snapshots.jsonl');M=readj(TASK/'models.json')['models']
assert [len(C),len(D),len(F),len(M),len(S)]==[32,384,64,416,64]
assert len({x['id'] for x in M})==416
for k,v in A['artifact_hashes'].items():assert digest(TASK/k)==v,k
models={x['id']:x for x in M}; contexts={x['id']:x for x in C};dirs={x['id']:x for x in D};snapshots={x['id']:x for x in S}
expected={(s,t,p) for s in P['seeds'] for t in P['teachers'] for p in P['prefix_budgets']}
assert {(c['seed'],c['teacher'],c['prefix']) for c in C}==expected
assert {(f['seed'],f['teacher'],f['prefix'],f['epsilon']) for f in F}=={(*x,e) for x in expected for e in P['epsilon_values']}
DATA=np.load(TASK/'data.npz',allow_pickle=False);PRED=np.load(TASK/'predictions.npz',allow_pickle=False);OPS=np.load(TASK/'operators.npz',allow_pickle=False)
operators={};features={};baseline_checks=0
with threadpool_limits(limits=4):
 for c in C:
  cid=c['id'];inp_path=TASK/c['context_evidence']['path'];assert digest(inp_path)==c['context_evidence']['sha256']
  with np.load(inp_path,allow_pickle=False) as cp:
   vals={k:cp[k] for k in cp.files}
  for k,v in vals.items():
   assert arrayhash(v)==c['data_hashes'][k],(cid,k)
   compare('consolidated_context_inputs',DATA[cid+'__'+k],v,0,0)
  n,m=len(vals['raw_train']),len(vals['raw_evaluation'])
  assert (n,m)==(128,256)
  for key,nrows,off in [('raw_train',n,'train'),('raw_evaluation',m,'evaluation')]:
   regenerated=np.random.default_rng(c['seed']+P['seed_offsets'][off]).normal(size=(nrows,4))
   compare('frozen_seed_inputs',vals[key],regenerated,0,0)
  noise=np.random.default_rng(c['seed']+P['seed_offsets']['label_noise']).normal(scale=P['train_noise_sigma'],size=n)
  compare('frozen_seed_noise',vals['train_noise'],noise,0,0)
  y=vals['base_actual_targets'];ynom=target(c['teacher'],vals['raw_train'])+noise
  compare('nominal_teacher_labels',vals['base_nominal_targets'],ynom,0,0)
  compare('native_base_labels',y,ynom.astype(np.float32).astype(float),0,0)
  for phase,count in [('pilot',2),('response',4)]:
   z=np.random.default_rng(c['seed']+P['seed_offsets'][phase]).normal(size=(count,n))
   compare('frozen_seed_directions',vals[phase+'_directions'],z,0,0)
  train=vals['binary_train'];eva=vals['binary_evaluation']
  thresholds=c['threshold_manifest']['thresholds'][:c['prefix']]
  for j,r in enumerate(thresholds):
   q=np.quantile(vals['raw_train'][:,r['raw_feature']],r['probability'],method='linear')
   compare('train_only_quantile',r['value'],q,0,0)
   compare('binary_threshold_train',train[:,j],vals['raw_train'][:,r['raw_feature']]>q,0,0)
   compare('binary_threshold_evaluation',eva[:,j],vals['raw_evaluation'][:,r['raw_feature']]>q,0,0)
  base=c['base_model_id'];lt=PRED[base+'__train__leaf_indices'];le=PRED[base+'__evaluation__leaf_indices'];lc=PRED[base+'__tree_leaf_counts']
  at=np.zeros((n,n));ae=np.zeros((m,n));eye=np.eye(n);eta=c['actual_learning_rate'];l2=c['actual_l2_leaf_reg']
  for it,count in enumerate(lc):
   residual=eye-at
   u=np.zeros((int(count),n))
   for leaf in range(int(count)):
    mask=lt[:,it]==leaf
    if mask.any():u[leaf]=residual[mask].sum(0)/(int(mask.sum())+l2)
   at=at+eta*u[lt[:,it]];ae=ae+eta*u[le[:,it]]
   if it+1 in (32,512):
    for split,mat in [('train',at),('evaluation',ae)]:
     expected_op=OPS[f'{cid}__t{it+1}__{split}']
     compare('independent_partition_operators',mat,expected_op,1e-10,0)
     compare('native_baseline_replay',mat@y,PRED[f'{base}__t{it+1}__{split}'],1e-10,0)
     operators[(cid,it+1,split)]=mat.copy()
     baseline_checks+=1
  traj=PRED[base+'__train__trajectory'];assert traj.shape==(513,n)
  sse=((traj-y)**2).sum(1);w=np.maximum(sse[:-1]-sse[1:],0)
  efc=np.asarray([1-np.sum(np.bincount(lt[:,i])*(np.bincount(lt[:,i])-1))/(n*(n-1)) for i in range(512)])
  compare('per_tree_efc',DATA[cid+'__per_tree_efc_proxy'],efc)
  compare('efc_weights',DATA[cid+'__efc_weights'],w)
  unique,inverse=np.unique(train,axis=0,return_inverse=True);count=np.bincount(inverse);means=np.bincount(inverse,weights=y)/count;floor=np.mean((y-means[inverse])**2)
  assert len(unique)==c['n_train_signatures']
  bf={'train_mse':float(np.mean((traj[-1]-y)**2)),'collision_mse_floor':float(floor),'trajectory_weighted_per_tree_efc_proxy':float(efc@w/w.sum()),'frozen_eval_noise_gain':float(np.square(ae).sum()/m),'frozen_train_noise_gain':float(np.square(at).sum()/n),'largest_train_singular_value':float(np.linalg.svd(at,compute_uv=False)[0])}
  for k,v in bf.items():compare('baseline_feature_'+k,c['base_features'][k],v)
  features[cid]=bf
 for row in M:
  assert digest(TASK/row['path'])==row['sha256']
  assert (TASK/row['path']).stat().st_size==row['bytes']
  assert digest(TASK/row['raw_evidence'])==row['raw_evidence_sha256']
  with np.load(TASK/row['raw_evidence'],allow_pickle=False) as fp:
   assert arrayhash(fp['actual_targets'])==row['actual_targets_sha256']
   for key in fp.files:
    joined=row['id']+'__'+key
    if joined in PRED:compare('raw_fit_prediction_leaf_binding',fp[key],PRED[joined],0,0)
    elif row['role']!='base':compare('raw_fit_label_binding',fp[key],DATA[joined],0,0)
    else:
     basekeys={'actual_targets':'base_actual_targets','native_targets':'base_native_targets','nominal_targets':'base_nominal_targets','initial_rounding_delta':'base_rounding_delta'}
     compare('raw_base_label_binding',fp[key],DATA[row['context_id']+'__'+basekeys[key]],0,0)
  required={'loss_function':'RMSE','depth':2,'boosting_type':'Plain','bootstrap_type':'No','leaf_estimation_method':'Gradient','leaf_estimation_iterations':1,'leaf_estimation_backtracking':'No','score_function':'L2','boost_from_average':False,'border_count':1,'grow_policy':'SymmetricTree','task_type':'CPU','l2_leaf_reg':1,'random_strength':0,'rsm':1,'model_shrink_rate':0}
  for key,value in required.items():assert row['resolved_parameters'][key]==value,(row['id'],key)
  assert row['threads']==4 and row['seed']==contexts[row['context_id']]['seed']+400000
  assert row['trees']==(32 if row['role']=='pilot' else 512)
 for d in D:
  cid=d['context_id'];base=contexts[cid]['base_model_id'];y=DATA[cid+'__base_actual_targets'];eps=d['epsilon'];fit=d['id']
  z=DATA[f'{cid}__{d["phase"]}_directions'][d['direction']]
  actual=(y+eps*z).astype(np.float32).astype(float)-y
  compare('native_perturbation_delta',DATA[fit+'__actual_delta'],actual,0,0)
  assert arrayhash(actual)==d['actual_delta_sha256']
  assert arrayhash(z)==d['nominal_z_sha256']
  assert d['valid']==bool(np.any(actual!=0))
  for split in ('train','evaluation'):
   keys=d['array_keys'][split];full=PRED[keys['prediction']]-PRED[f'{base}__t{d["trees"]}__{split}'];frozen=operators[(cid,d['trees'],split)]@actual;struct=full-frozen
   compare('full_response_arrays',PRED[keys['full_delta']],full,0,0)
   compare('frozen_response_arrays',PRED[keys['frozen_delta']],frozen,1e-10,0)
   compare('structural_response_arrays',PRED[keys['structural_delta']],struct,1e-10,0)
   den=len(full)*eps**2
   metrics={'normalized_full':float(full@full/den),'normalized_frozen':float(frozen@frozen/den),'normalized_structural_discrepancy':float(struct@struct/den),'normalized_twice_cross':float(2*frozen@struct/den)}
   for k,v in metrics.items():compare('response_metric_'+k,d['metrics'][split][k],v)
   clean=target(d['teacher'],DATA[cid+'__raw_'+split])
   compare('direction_clean_quality',d['clean_train_mse' if split=='train' else 'clean_evaluation_mse'],np.mean((PRED[keys['prediction']]-clean)**2))
 for f in F:
  for phase,key,count in [('pilot','cheap_discrepancy',2),('response','full_discrepancy',4)]:
   group=[d for d in D if d['context_id']==f['context_id'] and d['epsilon']==f['epsilon'] and d['phase']==phase]
   assert len(group)==count
   compare('endpoint_'+key,f[key],np.mean([d['metrics']['evaluation']['normalized_structural_discrepancy'] for d in group]))
  for k,v in features[f['context_id']].items():compare('forecast_base_feature',f[k],v)
  snap=snapshots[f['id']]
  assert not {'full_discrepancy','target_u','models'} & set(snap)
  for k,v in features[f['context_id']].items():compare('pre_response_feature_snapshot',snap[k],v)
  compare('pre_response_probe_snapshot',snap['cheap_discrepancy'],f['cheap_discrepancy'],0,0)
 if A['forecast']['status']=='complete_discovery_cross_validation':
  names=['log10_epsilon','log10_prefix','teacher_interaction','log10_1p_train_mse','collision_mse_floor','trajectory_weighted_per_tree_efc_proxy','log10_1p_frozen_eval_noise_gain','log10_1p_frozen_train_noise_gain','log10_1p_largest_train_singular_value','log10_1p_cheap_discrepancy']
  X=np.asarray([[math.log10(f['epsilon']),math.log10(f['prefix']),float(f['teacher']=='interaction'),math.log10(1+f['train_mse']),f['collision_mse_floor'],f['trajectory_weighted_per_tree_efc_proxy'],math.log10(1+f['frozen_eval_noise_gain']),math.log10(1+f['frozen_train_noise_gain']),math.log10(1+f['largest_train_singular_value']),math.log10(1+f['cheap_discrepancy'])] for f in F])
  y=np.asarray([math.log10(1+f['full_discrepancy']) for f in F]);preds={k:np.zeros(64) for k in ['B0','B1','B2','B3','B4','A']}
  cols={'B1':list(range(3)),'B2':list(range(9)),'B3':[0,1,2,9],'A':list(range(10))}
  for seed in P['seeds']:
   tr=np.asarray([f['seed']!=seed for f in F]);te=~tr
   preds['B0'][te]=y[tr].mean();preds['B4'][te]=X[te,9]+(y[tr]-X[tr,9]).mean()
   for mod,col in cols.items():
    xx=X[:,col];mu=xx[tr].mean(0);sd=xx[tr].std(0);sd[sd==0]=1
    z=(xx[tr]-mu)/sd;v=(xx[te]-mu)/sd;ym=y[tr].mean()
    augmented=np.vstack([z,np.eye(len(col))]);rhs=np.concatenate([y[tr]-ym,np.zeros(len(col))]);beta=np.linalg.lstsq(augmented,rhs,rcond=None)[0]
    preds[mod][te]=ym+v@beta
  for mod,pred in preds.items():
   compare('independent_OOF_'+mod,[f['models'][mod]['prediction_u'] for f in F],pred,1e-11,0)
   err=np.abs(pred-y)
   for seed in P['seeds']:compare('draw_MAE_'+mod,A['forecast']['summaries'][mod]['draw_mae_u'][str(seed)],err[[f['seed']==seed for f in F]].mean())
   for teacher in P['teachers']:compare('teacher_MAE_'+mod,A['forecast']['summaries'][mod]['teacher_mae_u'][teacher],err[[f['teacher']==teacher for f in F]].mean())
   compare('aggregate_MAE_'+mod,A['forecast']['summaries'][mod]['mae_u'],err.mean())
  compare('target_range',A['forecast']['target_q90_minus_q10'],np.quantile(y,.9)-np.quantile(y,.1))
totals={}
for c in C:
 for k,v in c['timings'].items():totals[k]=totals.get(k,0)+v
for k,v in totals.items():compare('timing_totals_'+k,A['timings'][k],v)
for prefix,phase in [('cheap','pilot'),('full','response')]:
 for key in ['fit','prediction','decomposition','leaf_evidence']:
  value=sum(d['timings'][key+'_seconds'] for d in D if d['phase']==phase)
  compare('direction_timing_totals_'+prefix+'_'+key,A['timings'][prefix+'_'+key+'_seconds'],value)
cheap=sum(totals['cheap_'+k+'_seconds'] for k in ['fit','prediction','decomposition']);full=sum(totals['full_'+k+'_seconds'] for k in ['fit','prediction','decomposition'])
compare('primary_cost_ratio',A['decision']['cheap_full_wall_ratio'],cheap/full)

print(json.dumps({'verified':True,'attempt':TASK.parents[1].name,'contexts':len(C),'directions':len(D),'model_and_fit_hashes_checked':len(M),'OOF_rows_checked':len(F),'baseline_replays_checked':baseline_checks,'max_errors':errors,'fits_performed':0,'native_model_inference_performed':0,'source_mutations':0},indent=2))
